use std::path::{Path, PathBuf};
use std::sync::Arc;

use serde_json::{json, Value};
use zero3_core::subagent::SubagentTask;
use zero3_skills::{FilesystemSkillProvider, SkillRegistry, SkillRoot};
use zero3_subagents::RouteRequest;

use super::{action_gate, AgentRunRequest, AppState};

pub(super) fn build_skill_registry(data_dir: &Path) -> anyhow::Result<Arc<SkillRegistry>> {
    let registry = Arc::new(SkillRegistry::new());
    let mut roots = Vec::new();

    if let Some(value) = std::env::var_os("ZERO3_SKILL_ROOTS") {
        for path in std::env::split_paths(&value) {
            roots.push(SkillRoot::new(path, "custom", 0));
        }
    }

    if let Ok(cwd) = std::env::current_dir() {
        roots.push(SkillRoot::new(cwd.join(".agents/skills"), "project-agents", 10));
        roots.push(SkillRoot::new(cwd.join(".codex/skills"), "project-codex", 11));
    }

    roots.push(SkillRoot::new(data_dir.join("skills"), "zero3-user", 20));

    if let Some(home) = std::env::var_os("HOME").or_else(|| std::env::var_os("USERPROFILE")) {
        let home = PathBuf::from(home);
        roots.push(SkillRoot::new(home.join(".agents/skills"), "user-agents", 30));
        roots.push(SkillRoot::new(home.join(".codex/skills"), "user-codex", 31));
    }

    registry.register_provider(Arc::new(FilesystemSkillProvider::new(roots)))?;
    Ok(registry)
}

pub(super) async fn execute_agent_request(
    state: &AppState,
    request: AgentRunRequest,
) -> anyhow::Result<Value> {
    let snapshot = state.skills.snapshot(None).await;
    let available_backends = state.agents.list();
    let routing_goal = if request.skills.is_empty() {
        request.goal.clone()
    } else {
        format!("{} {}", request.goal, request.skills.join(" "))
    };
    let decision = state.agent_router.route(RouteRequest {
        goal: &routing_goal,
        preferred_backend: Some(&request.backend),
        available_backends: &available_backends,
        skills: &snapshot.skills,
    })?;

    let explicitly_selected = !request.skills.is_empty();
    let selected_names = if explicitly_selected {
        request.skills.clone()
    } else {
        decision.matched_skills.clone()
    };
    if selected_names.len() > 8 {
        return Err(anyhow::anyhow!("at most 8 skills may be loaded for one task"));
    }

    let mut loaded_skills = Vec::new();
    for name in selected_names {
        let definition = state
            .skills
            .get(&name, None)
            .await?
            .ok_or_else(|| anyhow::anyhow!("requested skill {name:?} was not found"))?;
        if explicitly_selected && !definition.summary.invocation.user_invocable {
            return Err(anyhow::anyhow!(
                "skill {:?} is not user-invocable",
                definition.summary.name
            ));
        }
        if !explicitly_selected && !definition.summary.invocation.model_invocable {
            continue;
        }
        action_gate(
            request.approval.granted_level,
            request.approval.approved,
            "skill",
            &format!("invoke:{}", definition.summary.name),
            definition.summary.required_permission,
            true,
        )
        .map_err(|error| anyhow::anyhow!(error.message))?;
        loaded_skills.push(definition);
    }

    let skill_context = loaded_skills
        .iter()
        .map(|skill| {
            json!({
                "name": skill.summary.name,
                "description": skill.summary.description,
                "source": skill.summary.source,
                "provider": skill.summary.provider,
                "required_permission": skill.summary.required_permission,
                "content": clip_skill_content(&skill.content, 65_536),
            })
        })
        .collect::<Vec<_>>();
    let loaded_names = loaded_skills
        .iter()
        .map(|skill| skill.summary.name.clone())
        .collect::<Vec<_>>();
    let task = SubagentTask {
        goal: request.goal,
        context: json!({
            "user_context": request.context,
            "zero3": {
                "routing": &decision,
                "skills": skill_context,
                "skill_catalog_complete": snapshot.complete,
            }
        }),
    };

    let route = if request.backend == "auto" {
        std::iter::once(decision.backend.clone())
            .chain(decision.fallbacks.iter().cloned())
            .collect::<Vec<_>>()
    } else {
        vec![decision.backend.clone()]
    };
    let mut attempted_backends = Vec::new();
    let mut failures = Vec::new();
    for backend in route {
        attempted_backends.push(backend.clone());
        match state.agents.dispatch(&backend, task.clone()).await {
            Ok(result) => {
                return Ok(json!({
                    "summary": result.summary,
                    "output": result.output,
                    "routing": decision,
                    "skills": loaded_names,
                    "attempted_backends": attempted_backends,
                    "skill_catalog_complete": snapshot.complete,
                }));
            }
            Err(error) => failures.push(format!("{backend}: {error:#}")),
        }
    }

    Err(anyhow::anyhow!(
        "all routed agent backends failed: {}",
        failures.join(" | ")
    ))
}

fn clip_skill_content(content: &str, max_chars: usize) -> String {
    if content.chars().count() <= max_chars {
        return content.to_string();
    }
    content.chars().take(max_chars).collect()
}

#[cfg(test)]
mod tests {
    use super::clip_skill_content;

    #[test]
    fn skill_content_clipping_preserves_utf8_boundaries() {
        let value = "零三".repeat(100);
        let clipped = clip_skill_content(&value, 17);
        assert_eq!(clipped.chars().count(), 17);
        assert!(clipped.is_char_boundary(clipped.len()));
    }
}
